from pathlib import Path
path = Path('/src/mupdf/source/fitz/load-bmp.c')
data = path.read_text()
if '#include <stddef.h>' not in data:
    data = data.replace('#include <limits.h>
', '#include <limits.h>
#include <stddef.h>
')
old = "static const unsigned char *
bmp_read_palette(fz_context *ctx, struct info *info, const unsigned char *begin, const unsigned char *end, const unsigned char *p)
{
	int i, expected, present, entry_size;
	const unsigned char *bitmap;

	entry_size = palette_entry_size(info);
	bitmap = begin + info->bitmapoffset;

	expected = fz_mini(info->colors, 1 << info->bitcount);
	if (expected == 0)
		expected = 1 << info->bitcount;
	present = fz_mini(expected, (bitmap - p) / entry_size);
"
new = "static const unsigned char *
bmp_read_palette(fz_context *ctx, struct info *info, const unsigned char *begin, const unsigned char *end, const unsigned char *p)
{
	int i, expected, present, entry_size;
	const unsigned char *bitmap;
	ptrdiff_t avail;

	entry_size = palette_entry_size(info);
	bitmap = begin + info->bitmapoffset;	
	/* Malformed files can claim the bitmap starts before the palette.
	 * Clamp to avoid negative pointer differences and negative palette counts. */
	if (bitmap < p)
	{
		fz_warn(ctx, "bitmap offset precedes color table in bmp image");
		bitmap = p;
	}
	if (bitmap > end)
		bitmap = end;

	expected = fz_mini(info->colors, 1 << info->bitcount);
	if (expected == 0)
		expected = 1 << info->bitcount;
	avail = bitmap - p;
	if (avail < 0)
		avail = 0;
	present = fz_mini(expected, (int)(avail / entry_size));
"
if old not in data:
    raise SystemExit('pattern not found; file may have changed')
data = data.replace(old, new)
path.write_text(data)
print('patched', path)
